/**
 * Unit tests for BasicSerializerFactory#findSuppressableContentValue.
 * Since the method is protected, we use a Test subclass to expose it.
 */
public class BasicSerializerFactory_findSuppressableContentValue_TriageGen1Test {

    private TestableBasicSerializerFactory factory;
    private SerializationConfig mockConfig;
    private JavaType mockContentType;
    private BeanDescription mockBeanDesc;

    /**
     * Testable subclass to access the protected method.
     */
    private static class TestableBasicSerializerFactory extends BasicSerializerFactory {
        protected TestableBasicSerializerFactory(SerializerFactoryConfig config) {
            super(config);
        }

        @Override
        protected Iterable<com.fasterxml.jackson.databind.ser.JsonSerializer<?>> customSerializers() {
            return null;
        }

        @Override
        public Object findSuppressableContentValuePublic(SerializationConfig config, JavaType contentType, BeanDescription beanDesc) 
                throws JsonMappingException {
            return findSuppressableContentValue(config, contentType, beanDesc);
        }
    }

    @Before
    public void setUp() {
        factory = new TestableBasicSerializerFactory(null);
        mockConfig = Mockito.mock(SerializationConfig.class);
        mockContentType = Mockito.mock(JavaType.class);
        mockBeanDesc = Mockito.mock(BeanDescription.class);
    }

    @Test
    public void testFindSuppressableContentValue_ReturnsNullWhenInclusionIsNull() throws JsonMappingException {
        // Arrange
        when(mockBeanDesc.findSerializationInclusionForContent(null)).thenReturn(null);

        // Act
        Object result = factory.findSuppressableContentValuePublic(mockConfig, mockContentType, mockBeanDesc);

        // Assert
        assertNull("Result should be null when inclusion is null", result);
    }

    @Test
    public void testFindSuppressableContentValue_ReturnsNonEmptyWhenInclusionIsNonDefault() throws JsonMappingException {
        // Arrange
        // The code specifically handles NON_DEFAULT by mapping it to NON_EMPTY
        when(mockBeanDesc.findSerializationInclusionForContent(null)).thenReturn(JsonInclude.Include.NON_DEFAULT);

        // Act
        Object result = factory.findSuppressableContentValuePublic(mockConfig, mockContentType, mockBeanDesc);

        // Assert
        assertEquals("NON_DEFAULT should be treated as NON_EMPTY", JsonInclude.Include.NON_EMPTY, result);
    }

    @Test
    public void testFindSuppressableContentValue_ReturnsOriginalInclusionForOtherModes() throws JsonMappingException {
        // Arrange
        // Test with NON_NULL
        when(mockBeanDesc.findSerializationInclusionForContent(null)).thenReturn(JsonInclude.Include.NON_NULL);

        // Act
        Object result = factory.findSuppressableContentValuePublic(mockConfig, mockContentType, mockBeanDesc);

        // Assert
        assertEquals("Result should match the input inclusion (NON_NULL)", JsonInclude.Include.NON_NULL, result);

        // Arrange: Test with ALWAYS
        when(mockBeanDesc.findSerializationInclusionForContent(null)).thenReturn(JsonInclude.Include.ALWAYS);

        // Act
        result = factory.findSuppressableContentValuePublic(mockConfig, mockContentType, mockBeanDesc);

        // Assert
        assertEquals("Result should match the input inclusion (ALWAYS)", JsonInclude.Include.ALWAYS, result);
    }

    @Test
    public void testFindSuppressableContentValue_ReturnsOriginalInclusionForNonEmpty() throws JsonMappingException {
        // Arrange
        when(mockBeanDesc.findSerializationInclusionForContent(null)).thenReturn(JsonInclude.Include.NON_EMPTY);

        // Act
        Object result = factory.findSuppressableContentValuePublic(mockConfig, mockContentType, mockBeanDesc);

        // Assert
        assertEquals("Result should match the input inclusion (NON_EMPTY)", JsonInclude.Include.NON_EMPTY, result);
    }
}
